static int led_tg_check(const struct xt_tgchk_param *par)
{
	struct xt_led_info *ledinfo = par->targinfo;
	struct xt_led_info_internal *ledinternal;
	char name[sizeof(ledinfo->id) + 1];
	int err;

	if (ledinfo->id[0] == '\0')
		return -EINVAL;

	memcpy(name, ledinfo->id, sizeof(ledinfo->id));
	name[sizeof(ledinfo->id)] = '\0';

	mutex_lock(&xt_led_mutex);

	ledinternal = led_trigger_lookup(name);
	if (ledinternal) {
		ledinternal->refcnt++;
		goto out;
	}

	err = -ENOMEM;
	ledinternal = kzalloc(sizeof(struct xt_led_info_internal), GFP_KERNEL);
	if (!ledinternal)
		goto exit_mutex_only;

	ledinternal->trigger_id = kstrdup(name, GFP_KERNEL);

